        return pct < float(rule[1:-1])
    if rule.startswith('>'):
        return pct > float(rule[1:-1])
    lo, hi = rule[:-1].split('-')
    return float(lo.rstrip('%')) <= pct <= float(hi.rstrip('%'))

def volume_ok(rule, volume):
    if rule is None:
        return True
    def number(text):
        text = text.lower()
        return float(text[:-1]) * (1000 if text.endswith('k') else 1000000)
    if rule.startswith('<'):
        return volume < number(rule[1:])
    if rule.startswith('>'):
        return volume > number(rule[1:])
    lo, hi = rule.split('-')
    return number(lo) <= volume <= number(hi)

def matches(rule, tx, monthly):
    m = merchants[tx['merchant']]
    return (
        rule['card_scheme'] == tx['card_scheme']
        and (not rule['account_type'] or m['account_type'] in rule['account_type'])
        and capture_ok(rule['capture_delay'], m['capture_delay'])
        and fraud_level_ok(rule['monthly_fraud_level'], monthly['fraud_rate'])
        and volume_ok(rule['monthly_volume'], monthly['volume'])
        and (not rule['merchant_category_code'] or m['merchant_category_code'] in rule['merchant_category_code'])
        and (rule['is_credit'] is None or rule['is_credit'] == (tx['is_credit'] == 'True'))
        and (not rule['aci'] or tx['aci'] in rule['aci'])
        and (rule['intracountry'] is None or bool(rule['intracountry']) == (tx['issuing_country'] == tx['acquirer_country']))
    )

def fee(rule, value):
    return rule['fixed_amount'] + rule['rate'] * value / 10000.0

